import java.util.*;

public class Collect {
    public static void main(String[] args) {
        String[] words = {"to", "be", "or", "not", "to", "be"};

        Map<String, Integer> counts = new HashMap<>();       // key -> value.
        for (String w : words) counts.merge(w, 1, Integer::sum);
        System.out.println(counts.get("to"));                 // 2

        Set<String> unique = new LinkedHashSet<>(Arrays.asList(words));   // once each, in order.
        System.out.println(unique);                           // [to, be, or, not]

        Queue<Integer> fifo = new ArrayDeque<>(List.of(3, 1, 2));
        Queue<Integer> byPriority = new PriorityQueue<>(List.of(3, 1, 2));
        System.out.println(fifo.poll() + " " + byPriority.poll());   // 3 1
    }
}
```

| Need | Choose |
|---|---|
| positions, duplicates. | ArrayList. |
| uniqueness, fast lookup. | HashSet (LinkedHashSet to keep order). |
| key to value. | HashMap (TreeMap for sorted keys). |
| first in, first out. | ArrayDeque. |
| smallest first. | PriorityQueue. |

